{"command":"cat > /tmp/h2.py <<'PY'
import subprocess, time
def start(cmd,w=80,h=24,cwd="/tmp/test1",session="t"):
    subprocess.run(["tmux","kill-session","-t",session],capture_output=True)
    time.sleep(0.1)
    for attempt in range(5):
        r=subprocess.run(["tmux","new-session","-d","-s",session,"-x",str(w),"-y",str(h),"-c",cwd])
        if r.returncode==0: break
        time.sleep(0.3)
    else:
        raise RuntimeError("tmux new failed")
    subprocess.run(["tmux","send-keys","-t",session,cmd,"Enter"])
    time.sleep(0.8)
def keys(*ks,delay=0.12,session="t"):
    for k in ks:
        subprocess.run(["tmux","send-keys","-t",session,k]); time.sleep(delay)
def cap(session="t", colors=False):
    a=["tmux","capture-pane","-t",session,"-p"]
    if colors: a.append("-e")
    return subprocess.run(a,capture_output=True,text=True).stdout
PY
