use clap::{Arg, ArgAction, ArgGroup, Command};
use clap::builder::PossibleValuesParser;
use std::path::PathBuf;

pub const EDITORS: [&str; 19] = ["vim", "neovim", "nvim", "nano", "code", "vscode", "code-insiders", "emacs", "emacsclient", "hx", "helix", "subl", "sublime-text", "micro", "intellij", "goland", "pycharm", "less", "fresh"];

fn cli() -> Command {
    Command::new("igrep")
        .version(env!("CARGO_PKG_VERSION"))
        .about("Interactive Grep")
        .next_line_help(true)
        .group(ArgGroup::new("pattern_or_type_list").args(["pattern", "type_list"]).multiple(false))
        .arg(Arg::new("pattern").value_name("PATTERN").help("Regular expression used for searching").required(true).conflicts_with("type_list").index(1))
        .arg(Arg::new("paths").value_name("PATHS").help("Files or directories to search. Directories are searched recursively. If not specified, searching starts from current directory").num_args(0..).index(2).value_parser(clap::value_parser!(PathBuf)))
        .arg(Arg::new("editor").long("editor").value_name("EDITOR").help("Text editor used to open selected match").value_parser(PossibleValuesParser::new(EDITORS)).conflicts_with("custom_command"))
        .arg(Arg::new("custom_command").long("custom-command").value_name("CUSTOM_COMMAND").help("Custom command used to open selected match. Must contain {file_name} and {line_number} tokens").env("IGREP_CUSTOM_EDITOR"))
        .arg(Arg::new("theme").long("theme").value_name("THEME").help("UI color theme").default_value("dark").value_parser(PossibleValuesParser::new(["light", "dark"])))
        .arg(Arg::new("ignore_case").short('i').long("ignore-case").help("Searches case insensitively").action(ArgAction::SetTrue))
        .arg(Arg::new("smart_case").short('S').long("smart-case").help("Searches case insensitively if the pattern is all lowercase. Search case sensitively otherwise").action(ArgAction::SetTrue))
        .arg(Arg::new("hidden").short('.').long("hidden").help("Search hidden files and directories. By default, hidden files and directories are skipped").action(ArgAction::SetTrue))
        .arg(Arg::new("follow").short('L').long("follow").help("Follow symbolic links while traversing directories").action(ArgAction::SetTrue))
        .arg(Arg::new("word_regexp").short('w').long("word-regexp").help("Only show matches surrounded by word boundaries").action(ArgAction::SetTrue))
        .arg(Arg::new("fixed_strings").short('F').long("fixed-strings").help("Exact matches with no regex. Useful when searching for a string full of delimiters").action(ArgAction::SetTrue))
        .arg(Arg::new("multiline").short('U').long("multiline").help("Search with pattern contains newline character ('\\n')").action(ArgAction::SetTrue))
        .arg(Arg::new("glob").short('g').long("glob").value_name("GLOB").help("Include files and directories for searching that match the given glob. Multiple globs may be provided").action(ArgAction::Append))
        .arg(Arg::new("type_list").long("type-list").help("Show all supported file types and their corresponding globs").action(ArgAction::SetTrue).required(true).conflicts_with("pattern"))
        .arg(Arg::new("type_matching").short('t').long("type").value_name("TYPE_MATCHING").help("Only search files matching TYPE. Multiple types may be provided").action(ArgAction::Append))
        .arg(Arg::new("type_not").short('T').long("type-not").value_name("TYPE_NOT").help("Do not search files matching TYPE-NOT. Multiple types-not may be provided").action(ArgAction::Append))
        .arg(Arg::new("context_viewer").long("context-viewer").value_name("CONTEXT_VIEWER").help("Context viewer position at startup").default_value("none").value_parser(PossibleValuesParser::new(["none", "vertical", "horizontal"])))
        .arg(Arg::new("sort").long("sort").value_name("SORT_BY").help("Sort results, see ripgrep for details").value_parser(PossibleValuesParser::new(["path", "modified", "created", "accessed"])))
        .arg(Arg::new("sortr").long("sortr").value_name("SORT_BY_REVERSE").help("Sort results reverse, see ripgrep for details").value_parser(PossibleValuesParser::new(["path", "modified", "created", "accessed"])))
}

fn main() {
    let m = cli().get_matches();
    if m.get_flag("type_list") {
        print!("{}", include_str!("types.txt"));
        return;
    }
    println!("pattern={:?} paths={:?}", m.get_one::<String>("pattern"), m.get_many::<PathBuf>("paths").map(|v| v.collect::<Vec<_>>()));
}
