// ---------- Editor ----------
#[derive(Clone, Debug)]
enum EditorSpec {
    Program { program: String, args_template: Vec<String> },
    Custom { program: String, args: Vec<String> },
}
impl EditorSpec {
    fn program(&self) -> &str {
        match self { EditorSpec::Program { program, .. } => program, EditorSpec::Custom { program, .. } => program }
    }
    fn build_command_args(&self, file: &str, line: usize) -> (String, Vec<String>) {
        match self {
            EditorSpec::Program { program, args_template } => {
                let args = args_template.iter().map(|a| a.replace("{file_name}", file).replace("{line_number}", &line.to_string())).collect();
                (program.clone(), args)
            }
            EditorSpec::Custom { program, args } => {
                let args = args.iter().map(|a| a.replace("{file_name}", file).replace("{line_number}", &line.to_string())).collect();
                (program.clone(), args)
            }
        }
    }
}

fn editor_from_name(name: &str) -> Option<EditorSpec> {
    let (program, args): (&str, Vec<String>) = match name {
        "vim" => ("vim", vec!["+{line_number}".into(), "{file_name}".into()]),
        "neovim" | "nvim" => ("nvim", vec!["+{line_number}".into(), "{file_name}".into()]),
        "nano" => ("nano", vec!["+{line_number}".into(), "{file_name}".into()]),
        "code" | "vscode" => ("code", vec!["-g".into(), "{file_name}:{line_number}".into()]),
        "code-insiders" => ("code-insiders", vec!["-g".into(), "{file_name}:{line_number}".into()]),
        "emacs" => ("emacs", vec!["-nw".into(), "+{line_number}".into(), "{file_name}".into()]),
        "emacsclient" => ("emacsclient", vec!["-nw".into(), "+{line_number}".into(), "{file_name}".into()]),
        "hx" => ("hx", vec!["{file_name}:{line_number}".into()]),
        "helix" => ("helix", vec!["{file_name}:{line_number}".into()]),
        "subl" | "sublime-text" => ("subl", vec!["{file_name}:{line_number}".into()]),
        "micro" => ("micro", vec!["+{line_number}".into(), "{file_name}".into()]),
        "intellij" => ("idea", vec!["--line".into(), "{line_number}".into(), "{file_name}".into()]),
        "goland" => ("goland", vec!["--line".into(), "{line_number}".into(), "{file_name}".into()]),
        "pycharm" => ("pycharm", vec!["--line".into(), "{line_number}".into(), "{file_name}".into()]),
        "less" => ("less", vec!["+{line_number}".into(), "{file_name}".into()]),
        "fresh" => ("fresh", vec!["{file_name}:{line_number}".into()]),
        _ => return None,
    };
    Some(EditorSpec::Program { program: program.to_string(), args_template: args })
}

fn parse_custom_command(command: &str) -> Result<EditorSpec> {
    // Validation mirrors observed behavior.
    let after_first_space = match command.split_once(' ') {
        Some((_, rest)) => rest,
        None => {
            return Err(anyhow!("Incorrect editor command: '{}'", command))
                .context("dummy") // placeholder replaced below
        }
    };
    let _ = after_first_space;
    unreachable!()
}

fn custom_command_error(command: &str, reason: &str) -> anyhow::Error {
    // anyhow error with a source: construct via a simple error type.
    #[derive(Debug)]
    struct Reason(String);
    impl std::fmt::Display for Reason {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}", self.0) }
    }
    impl std::error::Error for Reason {}
    anyhow::Error::new(Reason(reason.to_string())).context(format!("Incorrect editor command: '{}'", command))
}

fn validate_custom_command(command: &str) -> Result<EditorSpec> {
    let rest = match command.split_once(' ') {
        Some((_, rest)) => rest,
        None => return Err(custom_command_error(command, "Expected program and its arguments")),
    };
    if rest.matches("{file_name}").count() != 1 {
        return Err(custom_command_error(command, "Expected one occurrence of '{file_name}'."));
    }
    if rest.matches("{line_number}").count() != 1 {
        return Err(custom_command_error(command, "Expected one occurrence of '{line_number}'."));
    }
    let mut parts = command.split_whitespace();
    let program = parts.next().unwrap_or("").to_string();
    let args: Vec<String> = parts.map(|s| s.to_string()).collect();
    Ok(EditorSpec::Custom { program, args })
}

fn resolve_editor(matches: &clap::ArgMatches) -> Result<EditorSpec> {
    if let Some(custom) = matches.get_one::<String>("custom_command") {
        return validate_custom_command(custom);
    }
    if let Some(name) = matches.get_one::<String>("editor") {
        // clap already validated possible values
        return Ok(editor_from_name(name).unwrap());
    }
    for var in ["IGREP_EDITOR", "VISUAL", "EDITOR"] {
        if let Ok(value) = env::var(var) {
            let name = value.rsplit('/').next().unwrap_or("");
            if let Some(ed) = editor_from_name(name) {
                return Ok(ed);
            } else {
                #[derive(Debug)]
                struct InvalidVariant(String);
                impl std::fmt::Display for InvalidVariant {
                    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "invalid variant: {}", self.0) }
                }
                impl std::error::Error for InvalidVariant {}
                return Err(anyhow::Error::new(InvalidVariant(name.to_string()))
                    .context(format!("\"{}\" read from ${}, possible variants: [{}]", value, var, EDITORS.join(", "))));
            }
        }
    }
    Ok(editor_from_name("vim").unwrap())
}

// ---------- Search configuration ----------
fn build_types(matches: &clap::ArgMatches) -> Result<Types> {
    let mut builder = TypesBuilder::new();
    for line in include_str!("types.txt").lines() {
        if line.is_empty() { continue; }
        if let Some((name, globs)) = line.split_once(": ") {
            for g in globs.split(", ") {
                let _ = builder.add(name, g);
            }
        }
    }
    if let Some(vals) = matches.get_many::<String>("type_matching") {
        for v in vals { builder.select(v); }
    }
    if let Some(vals) = matches.get_many::<String>("type_not") {
        for v in vals { builder.negate(v); }
    }
    Ok(builder.build()?)
}

fn build_search_config(matches: &clap::ArgMatches) -> Result<SearchConfig> {
    // globs first (observed error precedence), then types
    let mut ob = OverrideBuilder::new(".");
    let globs: Vec<String> = matches.get_many::<String>("glob").map(|v| v.cloned().collect()).unwrap_or_default();
    for g in &globs {
        ob.add(g)?;
    }
    let overrides = ob.build()?;
    let types = build_types(matches)?;

    let pattern = matches.get_one::<String>("pattern").cloned().unwrap_or_default();
    let paths: Vec<String> = match matches.get_many::<PathBuf>("paths") {
        Some(vals) => vals.map(|p| p.to_str().expect("Not valid UTF-8").to_string()).collect(),
        None => Vec::new(),
    };
    let paths = if paths.is_empty() { vec![".".to_string()] } else { paths };

    let sort_state = if let Some(s) = matches.get_one::<String>("sortr") {
        Some((SortKind::from_str(s), true))
    } else if let Some(s) = matches.get_one::<String>("sort") {
        Some((SortKind::from_str(s), false))
    } else { None };

    Ok(SearchConfig {
        pattern,
        paths,
        ignore_case: matches.get_flag("ignore_case"),
        smart_case: matches.get_flag("smart_case"),
        hidden: matches.get_flag("hidden"),
        follow: matches.get_flag("follow"),
        word_regexp: matches.get_flag("word_regexp"),
        fixed_strings: matches.get_flag("fixed_strings"),
        multiline: matches.get_flag("multiline"),
        overrides,
        types,
        sort_state,
    })
}

// ---------- App ----------
#[derive(Clone, Copy, PartialEq, Eq)]
enum SearchPhase { Searching, Finished }

struct SearchInput {
    value: String,
    cursor: usize, // char index
}
impl SearchInput {
    fn new(value: &str) -> Self { Self { value: value.to_string(), cursor: value.chars().count() } }
    fn char_len(&self) -> usize { self.value.chars().count() }
    fn byte_index(&self, char_idx: usize) -> usize {
        self.value.char_indices().nth(char_idx).map(|(i, _)| i).unwrap_or(self.value.len())
    }
    fn insert_char(&mut self, c: char) {
        let b = self.byte_index(self.cursor);
        self.value.insert(b, c);
        self.cursor += 1;
    }
    fn backspace(&mut self) {
        if self.cursor > 0 {
            let start = self.byte_index(self.cursor - 1);
            let end = self.byte_index(self.cursor);
            self.value.replace_range(start..end, "");
            self.cursor -= 1;
        }
    }
    fn delete(&mut self) {
        if self.cursor < self.char_len() {
            let start = self.byte_index(self.cursor);
            let end = self.byte_index(self.cursor + 1);
            self.value.replace_range(start..end, "");
        }
    }
    fn left(&mut self) { self.cursor = self.cursor.saturating_sub(1); }
    fn right(&mut self) { if self.cursor < self.char_len() { self.cursor += 1; } }
}

struct App {
    config: SearchConfig,
    editor: EditorSpec,
    theme: ThemeKind,
    results: Vec<FileResult>,
    selected: usize,
    filtered_out: usize,
    filtered_out_files: usize,
    phase: SearchPhase,
    error_message: Option<String>,
    receiver: Receiver<ig::searcher::SearchMessage>,
    viewer: ContextViewerKind,
    viewer_size: u16, // percent
    key_buffer: String,
    key_dead: bool,
    show_keymap: bool,
    keymap_scroll_y: usize,
    keymap_scroll_x: usize,
    keymap_view_height: usize,
    keymap_view_width: usize,
    search_popup: Option<SearchInput>,
    context_cache: ContextCache,
    list_offset: usize,
    need_terminal_reset: bool,
}

impl App {
    fn total_matches(&self) -> usize { self.results.iter().map(|f| f.matches.len()).sum() }
    fn visible_files(&self) -> usize { self.results.len() }

    fn selected_location(&self) -> Option<(usize, usize)> {
        // returns (file_index, match_index_in_file)
        let mut idx = self.selected;
        for (fi, f) in self.results.iter().enumerate() {
            if idx < f.matches.len() { return Some((fi, idx)); }
            idx -= f.matches.len();
        }
        None
    }
    fn selected_row(&self) -> usize {
        let mut row = 0usize;
        let mut idx = self.selected;
        for f in &self.results {
            if idx < f.matches.len() { return row + 1 + idx; }
            idx -= f.matches.len();
            row += 1 + f.matches.len();
        }
        row
    }

    fn restart_search(&mut self) {
        self.results.clear();
        self.selected = 0;
        self.filtered_out = 0;
        self.filtered_out_files = 0;
        self.phase = SearchPhase::Searching;
        self.error_message = None;
        self.list_offset = 0;
        let (tx, rx) = mpsc::channel();
        self.receiver = rx;
        ig::searcher::spawn_search(self.config.clone(), tx);
    }

    fn update_search(&mut self) -> bool {
        // returns true if should exit (channel disconnected before Finished)
        loop {
            match self.receiver.try_recv() {
                Ok(ig::searcher::SearchMessage::Result(fr)) => {
                    self.results.push(fr);
                }
                Ok(ig::searcher::SearchMessage::Finished) => {
                    self.phase = SearchPhase::Finished;
                }
                Err(TryRecvError::Empty) => return false,
                Err(TryRecvError::Disconnected) => {
                    return self.phase != SearchPhase::Finished;
                }
            }
        }
    }

    fn sort_by_key(&mut self, kind: SortKind) {
        let new_state = match self.config.sort_state {
            Some((k, rev)) if k == kind => Some((kind, !rev)),
            _ => Some((kind, false)),
        };
        self.config.sort_state = new_state;
        self.restart_search();
    }

    fn move_next(&mut self) {
        let total = self.total_matches();
        if total > 0 && self.selected + 1 < total { self.selected += 1; }
    }
    fn move_prev(&mut self) {
        if self.selected > 0 { self.selected -= 1; }
    }
    fn move_next_file(&mut self) {
        if let Some((fi, _)) = self.selected_location() {
            if fi + 1 < self.results.len() {
                let before: usize = self.results[..=fi].iter().map(|f| f.matches.len()).sum();
                self.selected = before;
            }
        }
    }
    fn move_prev_file(&mut self) {
        if let Some((fi, _)) = self.selected_location() {
            if fi > 0 {
                let before: usize = self.results[..fi - 1].iter().map(|f| f.matches.len()).sum();
                // first match of previous file: sum of matches in files before fi-1
                self.selected = before;
            }
        }
    }
    fn move_first(&mut self) { self.selected = 0; }
    fn move_last(&mut self) {
        let total = self.total_matches();
        if total > 0 { self.selected = total - 1; }
    }

    fn filter_selected(&mut self) {
        if let Some((fi, mi)) = self.selected_location() {
            let file_empty_after;
            {
                let f = &mut self.results[fi];
                f.matches.remove(mi);
                file_empty_after = f.matches.is_empty();
            }
            self.filtered_out += 1;
            if file_empty_after {
                self.results.remove(fi);
                self.filtered_out_files += 1;
            }
            let total = self.total_matches();
            if total == 0 { self.selected = 0; }
            else if self.selected >= total { self.selected = total - 1; }
        }
    }
    fn filter_current_file(&mut self) {
        if let Some((fi, _)) = self.selected_location() {
            let count = self.results[fi].matches.len();
            self.results.remove(fi);
            self.filtered_out += count;
            self.filtered_out_files += 1;
            let total = self.total_matches();
            if total == 0 { self.selected = 0; }
            else if self.selected >= total { self.selected = total - 1; }
        }
    }

    fn current_match(&self) -> Option<(&FileResult, &ig::searcher::FileMatch)> {
        let (fi, mi) = self.selected_location()?;
        Some((&self.results[fi], &self.results[fi].matches[mi]))
    }

    fn open_editor(&mut self) {
        let Some((file, m)) = self.current_match() else { return };
        let file_path = file.path.clone();
        let line = m.line_number;
        let (program, args) = self.editor.build_command_args(&file_path, line);
        match ProcCommand::new(&program).args(&args).status() {
            Ok(_status) => {
                self.need_terminal_reset = true;
            }
            Err(_) => {
                self.error_message = Some(format!("Failed to open editor '{}'. Is it installed?", program));
            }
        }
    }
}

