fn keymap_text_lines() -> Vec<String> {
    let mut lines = Vec::new();
    lines.push(format!(" {:<19}│ {:<38} ", "Key(s)", "Action"));
    lines.push(format!(" {}┼{} ", "─".repeat(19), "─".repeat(39)));
    // rows excluding the final placeholder (we have 26 meaningful rows inc blank separators)
    for (k, a) in KEYMAP_ROWS.iter().take(26) {
        lines.push(format!(" {:<19}│ {:<38} ", k, a));
    }
    lines.push(String::new());
    lines.push(" Press any key to close…".to_string());
    lines
}

// ---------- Rendering ----------
impl App {
    fn status_label(&self) -> (&'static str, Color) {
        if self.error_message.is_some() {
            ("ERROR", Color::Red)
        } else {
            match self.phase {
                SearchPhase::Searching => ("SEARCHING", Color::Rgb(255, 165, 0)),
                SearchPhase::Finished => ("FINISHED", Color::Green),
            }
        }
    }

    fn draw(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(0), Constraint::Length(1)])
            .split(area);
        let body = chunks[0];
        let status_area = chunks[1];

        // Determine viewer areas
        let (results_area, viewer_area) = match self.viewer {
            ContextViewerKind::None => (body, None),
            ContextViewerKind::Vertical => {
                let parts = Layout::default().direction(Direction::Horizontal)
                    .constraints([Constraint::Percentage(100 - self.viewer_size), Constraint::Percentage(self.viewer_size)])
                    .split(body);
                (parts[0], Some(parts[1]))
            }
            ContextViewerKind::Horizontal => {
                let parts = Layout::default().direction(Direction::Vertical)
                    .constraints([Constraint::Percentage(100 - self.viewer_size), Constraint::Percentage(self.viewer_size)])
                    .split(body);
                (parts[0], Some(parts[1]))
            }
        };

        // update list scroll offset
        if !self.results.is_empty() {
            let inner_h = results_area.height.saturating_sub(2) as usize;
            if inner_h > 0 {
                let sel_row = self.selected_row();
                if sel_row < self.list_offset {
                    self.list_offset = sel_row.saturating_sub(1);
                }
                if sel_row >= self.list_offset + inner_h {
                    self.list_offset = sel_row + 1 - inner_h;
                }
            }
        } else {
            // keep offset as-is (original does not clamp on empty)
        }

        // Build result lines
        let mut lines: Vec<Line> = Vec::new();
        let mut global_idx = 0usize;
        for f in &self.results {
            let display = f.display_path();
            lines.push(Line::from(Span::styled(display, Style::default().fg(Color::LightMagenta))));
            for m in &f.matches {
                let mut spans: Vec<Span> = Vec::new();
                spans.push(Span::styled(format!(" {}: ", m.line_number), Style::default().fg(Color::Green)));
                let mut pos = 0usize;
                for &(s, e) in &m.spans {
                    let s = s.min(m.line_text.len());
                    let e = e.min(m.line_text.len());
                    if s > pos {
                        spans.push(Span::raw(m.line_text[pos..s].to_string()));
                    }
                    if e > s {
                        spans.push(Span::styled(m.line_text[s..e].to_string(), Style::default().fg(Color::Red)));
                    }
                    pos = pos.max(e);
                }
                if pos < m.line_text.len() {
                    spans.push(Span::raw(m.line_text[pos..].to_string()));
                }
                let mut line = Line::from(spans);
                if global_idx == self.selected {
                    line = line.style(Style::default().bg(self.theme.selected_bg()));
                }
                lines.push(line);
                global_idx += 1;
            }
        }
        let results_block = Block::default().borders(Borders::ALL).border_type(BorderType::Rounded);
        let results_widget = Paragraph::new(lines).block(results_block).scroll((self.list_offset as u16, 0));
        frame.render_widget(results_widget, results_area);

        // Context viewer
        if let Some(varea) = viewer_area {
            let vblock = Block::default().borders(Borders::ALL).border_type(BorderType::Rounded);
            if let Some((file, m)) = self.current_match() {
                let path = file.path.clone();
                let line_no = m.line_number;
                self.context_cache.ensure(&path, self.theme);
                let mut vlines: Vec<Line> = Vec::new();
                for (i, ctx_line) in self.context_cache.lines.iter().enumerate() {
                    let mut l = Line::from(ctx_line.spans.clone());
                    if i + 1 == line_no {
                        l = l.style(Style::default().bg(self.theme.selected_bg()));
                    }
                    vlines.push(l);
                }
                let skip = (line_no - 1).saturating_sub((varea.height as usize) / 2);
                let widget = Paragraph::new(vlines).block(vblock).scroll((skip as u16, 0));
                frame.render_widget(widget, varea);
            } else {
                let widget = Paragraph::new(Vec::<Line>::new()).block(vblock);
                frame.render_widget(widget, varea);
            }
        }

        // Status bar
        self.draw_status(frame, status_area);

        // Keymap popup
        if self.show_keymap {
            self.draw_keymap(frame, area);
        }
        // Search popup
        if let Some(input) = &self.search_popup {
            self.draw_search_popup(frame, area, input);
        }
    }

    fn draw_status(&self, frame: &mut Frame, area: Rect) {
        let (label, label_color) = self.status_label();
        // label centered in 12 cells (ceil left padding)
        let label_len = label.chars().count();
        let total_pad = 12usize.saturating_sub(label_len);
        let left_pad = (total_pad + 1) / 2;
        let right_pad = total_pad - left_pad;
        let status_style = self.theme.status_style();
        let mut spans: Vec<Span> = Vec::new();
        spans.push(Span::styled(" ".repeat(left_pad), Style::default().bg(label_color)));
        spans.push(Span::styled(label.to_string(), Style::default().fg(Color::Black).bg(label_color).add_modifier(Modifier::BOLD)));
        spans.push(Span::styled(" ".repeat(right_pad), Style::default().bg(label_color)));
        let message = if self.error_message.is_some() {
            format!(" {}", self.error_message.as_ref().unwrap())
        } else if self.phase == SearchPhase::Searching {
            " ".to_string()
        } else if self.total_matches() == 0 && self.filtered_out == 0 {
            " No matches found.".to_string()
        } else {
            let total_m = self.total_matches() + self.filtered_out;
            let total_f = self.visible_files() + self.filtered_out_files;
            let mut msg = format!(" Found {} {} in {} {}{}",
                total_m,
                if total_m == 1 { "match" } else { "matches" },
                total_f,
                if total_f == 1 { "file" } else { "files" },
                if self.filtered_out > 0 { format!(" ({} filtered out)", self.filtered_out) } else { String::new() },
            );
            msg.push('.');
            // The format above puts '.' after parenthesis correctly; for non-filtered, msg ends with '.' already via push
            msg
        };
        // Fix double period handling: our msg currently may end with ".." if we included '.'; check
        spans.push(Span::styled(message, status_style));
        let line = Line::from(spans);
        let widget = Paragraph::new(line).style(status_style);
        frame.render_widget(widget, area);

        // Right side: key buffer + position
        let total = self.total_matches();
        let cur = if total == 0 { 0 } else { self.selected + 1 };
        let width = total.to_string().len();
        let pos_text = format!("{:>width$}/{}", cur, total, width = width);
        let key_disp = if self.key_buffer.is_empty() {
            String::new()
        } else if self.key_dead {
            self.key_buffer.clone()
        } else {
            format!("{}…", self.key_buffer)
        };
        let right_text = if key_disp.is_empty() {
            format!("| {} ", pos_text)
        } else {
            format!("{} | {} ", key_disp, pos_text)
        };
        let right_width = right_text.chars().count() as u16;
        if area.width > 0 && right_width > 0 {
            let x = area.x + area.width.saturating_sub(right_width);
            let rect = Rect::new(x, area.y, right_width.min(area.width), 1);
            let w = Paragraph::new(right_text).style(status_style);
            frame.render_widget(w, rect);
        }
    }

    fn draw_keymap(&mut self, frame: &mut Frame, area: Rect) {
        let width = std::cmp::min((area.width as u32 * 4 / 5) as u16, 63).max(1);
        let height = std::cmp::min((area.height as u32 * 4 / 5) as u16, 34).max(1);
        let x = area.x + (area.width.saturating_sub(width)) / 2;
        let y = area.y + (area.height.saturating_sub(height)) / 2;
        let popup = Rect::new(x, y, width, height);
        frame.render_widget(Clear, popup);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Plain)
            .title(format!(" igrep {} ", env!("CARGO_PKG_VERSION")))
            .title_alignment(Alignment::Center)
            .border_style(Style::default().fg(Color::Green))
            .padding(Padding::vertical(1));
        let inner = block.inner(popup);
        self.keymap_view_height = inner.height as usize;
        self.keymap_view_width = inner.width as usize;
        let lines = keymap_text_lines();
        let text_lines: Vec<Line> = lines.iter().map(|l| Line::raw(l.clone())).collect();
        let widget = Paragraph::new(text_lines).block(block).scroll((self.keymap_scroll_y as u16, self.keymap_scroll_x as u16));
        frame.render_widget(widget, popup);
    }

    fn draw_search_popup(&self, frame: &mut Frame, area: Rect, input: &SearchInput) {
        // geometry: width ~50% using percentage boundary rounding, height 3 centered
        let w = area.width as u32;
        let start_x = ((w * 25 + 50) / 100) as u16;
        let end_x = ((w * 75 + 50) / 100) as u16;
        let width = end_x.saturating_sub(start_x).max(1);
        let height = 3u16.min(area.height.max(1));
        let x = area.x + start_x;
        let y = area.y + area.height.saturating_sub(height) / 2;
        let popup = Rect::new(x, y, width, height);
        frame.render_widget(Clear, popup);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Plain)
            .title(" Regex Pattern ")
            .title_alignment(Alignment::Center)
            .border_style(Style::default().fg(Color::Green).add_modifier(Modifier::BOLD));
        let inner = block.inner(popup);
        // Build display text: leading blank; if long, ellipsis + last 35 chars
        let chars: Vec<char> = input.value.chars().collect();
        let display = if chars.len() <= 36 {
            format!(" {}", input.value)
        } else {
            let start = chars.len() - 35;
            let tail: String = chars[start..].iter().collect();
            format!(" …{}", tail)
        };
        let widget = Paragraph::new(display).block(block);
        frame.render_widget(widget, popup);
        // cursor
        let cursor_x = popup.x + 2 + input.cursor as u16;
        let max_x = popup.x + popup.width.saturating_sub(2);
        let cx = cursor_x.min(max_x);
        let cy = popup.y + 1;
        if popup.height >= 2 {
            frame.set_cursor_position((cx, cy));
        }
        let _ = inner;
    }
}

// ---------- Terminal helpers ----------
fn init_terminal() -> Result<Terminal<CrosstermBackend<Stdout>>> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, crossterm::cursor::Hide, crossterm::event::EnableMouseCapture, EnterAlternateScreen, crossterm::event::DisableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let terminal = Terminal::new(backend)?;
    Ok(terminal)
}
fn restore_terminal(terminal: &mut Terminal<CrosstermBackend<Stdout>>) -> Result<()> {
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    disable_raw_mode()?;
    terminal.show_cursor()?;
    Ok(())
}

// ---------- Event handling ----------
enum Action { None, Quit }

impl App {
    fn handle_key(&mut self, key: KeyEvent) -> Action {
        // Mode: keymap popup
        if self.show_keymap {
            self.handle_keymap_key(key);
            return Action::None;
        }
        if self.search_popup.is_some() {
            return self.handle_search_key(key);
        }
        // main mode
        if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
            return Action::Quit;
        }
        match key.code {
            KeyCode::Esc => return Action::Quit,
            KeyCode::Char(c) => self.handle_char(c),
            KeyCode::Down => { self.clear_key_buffer(); self.move_next(); }
            KeyCode::Up => { self.clear_key_buffer(); self.move_prev(); }
            KeyCode::Right | KeyCode::PageDown => { self.clear_key_buffer(); self.move_next_file(); }
            KeyCode::Left | KeyCode::PageUp => { self.clear_key_buffer(); self.move_prev_file(); }
            KeyCode::Home => { self.clear_key_buffer(); self.move_first(); }
            KeyCode::End => { self.clear_key_buffer(); self.move_last(); }
            KeyCode::Delete => { self.clear_key_buffer(); self.filter_selected(); }
            KeyCode::Enter => { self.clear_key_buffer(); self.open_editor(); }
            KeyCode::F(1) => { self.clear_key_buffer(); self.open_keymap(); }
            KeyCode::F(5) => { self.clear_key_buffer(); self.open_search_popup(); }
            _ => { self.clear_key_buffer(); }
        }
        Action::None
    }

    fn clear_key_buffer(&mut self) {
        self.key_buffer.clear();
        self.key_dead = false;
    }
    fn set_dead_buffer(&mut self, s: String) {
        self.key_buffer = s;
        self.key_dead = true;
    }

    fn handle_char(&mut self, c: char) {
        if self.key_dead {
            self.key_buffer.clear();
            self.key_dead = false;
        }
        self.key_buffer.push(c);
        let buf = self.key_buffer.clone();
        // exact matches
        match buf.as_str() {
            "gg" => { self.clear_key_buffer(); self.move_first(); return; }
            "dd" => { self.clear_key_buffer(); self.filter_selected(); return; }
            "dw" => { self.clear_key_buffer(); self.filter_current_file(); return; }
            _ => {}
        }
        if buf.len() == 1 {
            // prefixes
            if buf == "g" || buf == "d" {
                self.key_dead = false; // pending (shows with …)
                return;
            }
            // single-char commands
            let handled = match c {
                'q' => { /* handled by caller? signal via buffer */ 
                    // We need quit: encode by setting a flag? Instead panic-free: use a special: clear and request quit via field
                    true
                }
                _ => false,
            };
            if handled {
                // quit handled in handle_key_main wrapper via checking
                self.key_buffer = "\u{1}q".to_string();
                return;
            }
            match c {
                '?' => { self.clear_key_buffer(); self.open_keymap(); }
                'j' => { self.clear_key_buffer(); self.move_next(); }
                'k' => { self.clear_key_buffer(); self.move_prev(); }
                'l' => { self.clear_key_buffer(); self.move_next_file(); }
                'h' => { self.clear_key_buffer(); self.move_prev_file(); }
                'G' => { self.clear_key_buffer(); self.move_last(); }
                'v' => { self.clear_key_buffer(); self.toggle_viewer(ContextViewerKind::Vertical); }
                's' => { self.clear_key_buffer(); self.toggle_viewer(ContextViewerKind::Horizontal); }
                '+' => { self.clear_key_buffer(); self.viewer_size = (self.viewer_size + 5).min(80); }
                '-' => { self.clear_key_buffer(); self.viewer_size = self.viewer_size.saturating_sub(5).max(20); }
                '/' => { self.clear_key_buffer(); self.open_search_popup(); }
                'n' => { self.clear_key_buffer(); self.sort_by_key(SortKind::Path); }
                'm' => { self.clear_key_buffer(); self.sort_by_key(SortKind::Modified); }
                'c' => { self.clear_key_buffer(); self.sort_by_key(SortKind::Created); }
                'a' => { self.clear_key_buffer(); self.sort_by_key(SortKind::Accessed); }
                _ => { self.set_dead_buffer(buf); }
            }
        } else {
            // two+ chars, not a known sequence
            self.set_dead_buffer(buf);
        }
    }

    fn open_keymap(&mut self) {
        self.show_keymap = true;
        self.keymap_scroll_y = 0;
        self.keymap_scroll_x = 0;
    }
    fn open_search_popup(&mut self) {
        self.search_popup = Some(SearchInput::new(&self.config.pattern.clone()));
    }
    fn toggle_viewer(&mut self, kind: ContextViewerKind) {
        if self.viewer == kind { self.viewer = ContextViewerKind::None; }
        else { self.viewer = kind; }
    }

    fn handle_keymap_key(&mut self, key: KeyEvent) {
        let max_y = {
            let total = keymap_text_lines().len();
            total.saturating_sub(self.keymap_view_height.max(1))
        };
        let max_x = {
            let longest = keymap_text_lines().iter().map(|l| l.chars().count()).max().unwrap_or(0);
            longest.saturating_sub(self.keymap_view_width.max(1))
        };
        match key.code {
            KeyCode::Down => { self.keymap_scroll_y = (self.keymap_scroll_y + 1).min(max_y); }
            KeyCode::Up => { self.keymap_scroll_y = self.keymap_scroll_y.saturating_sub(1); }
            KeyCode::Right => { self.keymap_scroll_x = (self.keymap_scroll_x + 1).min(max_x); }
            KeyCode::Left => { self.keymap_scroll_x = self.keymap_scroll_x.saturating_sub(1); }
            KeyCode::Char('j') => { self.keymap_scroll_y = (self.keymap_scroll_y + 1).min(max_y); }
            KeyCode::Char('k') => { self.keymap_scroll_y = self.keymap_scroll_y.saturating_sub(1); }
            KeyCode::Char('l') => { self.keymap_scroll_x = (self.keymap_scroll_x + 1).min(max_x); }
            KeyCode::Char('h') => { self.keymap_scroll_x = self.keymap_scroll_x.saturating_sub(1); }
            _ => { self.show_keymap = false; }
        }
    }

    fn handle_search_key(&mut self, key: KeyEvent) -> Action {
        // Ctrl+C cancels (char 'c' with CONTROL)
        if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
            self.search_popup = None;
            return Action::None;
        }
        match key.code {
            KeyCode::Esc => { self.search_popup = None; }
            KeyCode::Enter => {
                if let Some(input) = self.search_popup.take() {
                    self.config.pattern = input.value;
                    self.restart_search();
                }
            }
            KeyCode::Backspace => { if let Some(i) = &mut self.search_popup { i.backspace(); } }
            KeyCode::Delete => { if let Some(i) = &mut self.search_popup { i.delete(); } }
            KeyCode::Left => { if let Some(i) = &mut self.search_popup { i.left(); } }
            KeyCode::Right => { if let Some(i) = &mut self.search_popup { i.right(); } }
            KeyCode::Char(c) => {
                let mods = key.modifiers;
                if !mods.contains(KeyModifiers::CONTROL) && !mods.contains(KeyModifiers::ALT) {
                    if let Some(i) = &mut self.search_popup { i.insert_char(c); }
                }
            }
            _ => {}
        }
        Action::None
    }
}

fn main() -> Result<()> {
    let matches = parse_cli();
    if matches.get_flag("type_list") {
        print!("{}", include_str!("types.txt"));
        return Ok(());
    }
    // Paths conversion may panic on non-UTF8 (expected)
    let config = build_search_config(&matches)?;
    let editor = resolve_editor(&matches)?;
    let theme = match matches.get_one::<String>("theme").map(|s| s.as_str()) {
        Some("light") => ThemeKind::Light,
        _ => ThemeKind::Dark,
    };
    let viewer = match matches.get_one::<String>("context_viewer").map(|s| s.as_str()) {
        Some("vertical") => ContextViewerKind::Vertical,
        Some("horizontal") => ContextViewerKind::Horizontal,
        _ => ContextViewerKind::None,
    };
    let (tx, rx) = mpsc::channel();
    let mut app = App {
        config,
        editor,
        theme,
        results: Vec::new(),
        selected: 0,
        filtered_out: 0,
        filtered_out_files: 0,
        phase: SearchPhase::Searching,
        error_message: None,
        receiver: rx,
        viewer,
        viewer_size: 50,
        key_buffer: String::new(),
        key_dead: false,
        show_keymap: false,
        keymap_scroll_y: 0,
        keymap_scroll_x: 0,
        keymap_view_height: 15,
        keymap_view_width: 59,
        search_popup: None,
        context_cache: ContextCache::new(),
        list_offset: 0,
        need_terminal_reset: false,
    };
    ig::searcher::spawn_search(app.config.clone(), tx);

    let mut terminal = init_terminal()?;
    let result = run_app(&mut terminal, &mut app);
    let restore = restore_terminal(&mut terminal);
    result.and(restore)
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<Stdout>>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|frame| app.draw(frame))?;
        if app.need_terminal_reset {
            // handled after editor below; flag is set in open_editor, but we get here only after event handling
            app.need_terminal_reset = false;
        }
        if event::poll(Duration::from_millis(100))? {
            let ev = event::read()?;
            if let Event::Key(key) = ev {
                // check quit request encoded from char handling
                let action = app.handle_key(key);
                if matches!(action, Action::Quit) { break; }
                if app.key_buffer == "\u{1}q" {
                    app.key_buffer.clear();
                    break;
                }
                if app.need_terminal_reset {
                    app.need_terminal_reset = false;
                    // Re-create terminal (editor messed up screen)
                    // Show cursor of old, then init new
                    let _ = terminal.show_cursor();
                    let mut new_term = init_terminal()?;
                    std::mem::swap(terminal, &mut new_term);
                    // drop old (new_term variable holds old terminal)
                    drop(new_term);
                    // Force full redraw: new terminal has empty buffers
                    terminal.draw(|frame| app.draw(frame))?;
                }
            }
        }
        if app.update_search() {
            break;
        }
    }
    Ok(())
}
