// Post-process clap UnknownArgument errors so that arguments belonging to a
// mutually-exclusive group are shown as a group (as the original clap version
// used by the observed binary did).
fn fix_unknown_usage(rendered: &str, argv: &[String]) -> String {
    // extract suggested arg, if any
    let suggested = rendered.lines().find_map(|l| {
        let l = l.trim();
        if l.starts_with("a similar argument exists:") {
            l.split('\'').nth(1).map(|s| s.to_string())
        } else { None }
    });
    // find usage line
    let mut out_lines: Vec<String> = Vec::new();
    for line in rendered.lines() {
        if line.starts_with("Usage: ") {
            out_lines.push(fix_usage_line(line, argv, suggested.as_deref()));
        } else {
            out_lines.push(line.to_string());
        }
    }
    let mut s = out_lines.join("\n");
    if rendered.ends_with('\n') { s.push('\n'); }
    s
}

#[derive(Debug, Clone, PartialEq)]
enum Spec { Tok(String), Paths, Options }
fn tokenize_usage(rest: &str) -> Vec<String> {
    // Split into spec tokens; a "--opt <VAL>" pair stays together, "<PATTERN>" alone is a token.
    let mut toks = Vec::new();
    let mut it = rest.split_whitespace().peekable();
    while let Some(t) = it.next() {
        if t.starts_with("--") {
            if let Some(n) = it.peek() {
                if n.starts_with('<') && n.ends_with('>') {
                    toks.push(format!("{} {}", t, n));
                    it.next();
                    continue;
                }
            }
            toks.push(t.to_string());
        } else {
            toks.push(t.to_string());
        }
    }
    toks
}

fn fix_usage_line(line: &str, argv: &[String], suggested: Option<&str>) -> String {
    // Only transform when a group member is used/suggested.
    let (bin, rest) = match line.split_once(' ') {
        Some((b, r)) => (b.to_string(), r),
        None => return line.to_string(),
    };
    let rest = rest.strip_prefix("Usage: ").unwrap_or(rest);
    // NOTE: `line` here starts with bin already? Our caller passes full "Usage: bin ..." line.
    // Recompute properly:
    let _ = (bin, rest);
    let after = line.strip_prefix("Usage: ").unwrap_or(line);
    let (bin_name, usage_rest) = match after.split_once(' ') {
        Some((b, r)) => (b.to_string(), r),
        None => return line.to_string(),
    };
    let toks = tokenize_usage(usage_rest);
    // Determine activation.
    // Find unknown token from argv: first token that looks like the unexpected one is not known;
    // instead determine used args by scanning argv for known flags/positionals up to a token
    // starting with '-' that is not a known option (unknown), or end.
    let known_opts_with_value = ["--editor", "--custom-command", "--theme", "--glob", "-g", "--type", "-t", "--type-not", "-T", "--context-viewer", "--sort", "--sortr"];
    let mut used: Vec<String> = Vec::new();
    let mut i = 0usize;
    let mut positional_seen = false;
    let mut after_dd = false;
    while i < argv.len() {
        let a = &argv[i];
        if after_dd {
            if !positional_seen { used.push("<PATTERN>".into()); positional_seen = true; }
            i += 1; continue;
        }
        if a == "--" { after_dd = true; i += 1; continue; }
        if a == "--type-list" { used.push("--type-list".into()); }
        else if a == "--editor" || a.starts_with("--editor=") { used.push("--editor <EDITOR>".into()); }
        else if a == "--custom-command" || a.starts_with("--custom-command=") { used.push("--custom-command <CUSTOM_COMMAND>".into()); }
        else if known_opts_with_value.contains(&a.as_str()) {
            // skip its value for positional detection
            i += 2; continue;
        }
        else if a.starts_with('-') && a.len() > 1 {
            // unknown or flag: if it is a known flag, record nothing group-relevant; else stop (this is the unknown)
            let known_flags = ["--ignore-case", "-i", "--smart-case", "-S", "--hidden", "-.", "--follow", "-L", "--word-regexp", "-w", "--fixed-strings", "-F", "--multiline", "-U", "--help", "-h", "--version", "-V"];
            if known_flags.contains(&a.as_str()) || (a.starts_with('-') && !a.starts_with("--") && a[1..].chars().all(|c| "iSLwFU.h".contains(c))) {
                // combined known flags
            } else {
                break;
            }
        } else {
            if !positional_seen { used.push("<PATTERN>".into()); positional_seen = true; }
        }
        i += 1;
    }
    let pattern_group_members = ["--type-list", "<PATTERN>"];
    let editor_group_members = ["--editor <EDITOR>", "--custom-command <CUSTOM_COMMAND>"];
    let group_of = |tok: &str| -> Option<&'static str> {
        if pattern_group_members.contains(&tok) { Some("pattern") }
        else if editor_group_members.contains(&tok) { Some("editor") }
        else { None }
    };
    // activation order
    let mut activated: Vec<&'static str> = Vec::new();
    for u in &used {
        if let Some(g) = group_of(u) {
            if !activated.contains(&g) { activated.push(g); }
        }
    }
    if let Some(sug) = suggested {
        let g = match sug {
            "--type-list" => Some("pattern"),
            "--editor" | "--custom-command" => Some("editor"),
            _ => None,
        };
        if let Some(g) = g { if !activated.contains(&g) { activated.push(g); } }
    }
    if activated.is_empty() { return line.to_string(); }
    // Build new token list.
    let group_tok = |g: &str| -> String {
        match g {
            "pattern" => "<PATTERN|--type-list>".to_string(),
            _ => "<--editor <EDITOR>|--custom-command <CUSTOM_COMMAND>>".to_string(),
        }
    };
    // Remove specs belonging to activated groups, remember index of last removed.
    let mut new_toks: Vec<String> = Vec::new();
    let mut last_removed_index: Option<usize> = None; // index in new_toks where groups should be inserted
    for t in &toks {
        if t == "[PATHS]..." {
            // groups inserted before paths if not yet inserted
            if let Some(idx) = last_removed_index {
                let groups: Vec<String> = activated.iter().map(|g| group_tok(g)).collect();
                let pos = idx.min(new_toks.len());
                for (k, gt) in groups.into_iter().enumerate() { new_toks.insert(pos + k, gt); }
                last_removed_index = None;
            }
            new_toks.push(t.clone());
            continue;
        }
        if let Some(g) = group_of(t) {
            if activated.contains(&g) {
                last_removed_index = Some(new_toks.len());
                continue;
            }
        }
        new_toks.push(t.clone());
    }
    if let Some(idx) = last_removed_index {
        let groups: Vec<String> = activated.iter().map(|g| group_tok(g)).collect();
        let pos = idx.min(new_toks.len());
        for (k, gt) in groups.into_iter().enumerate() { new_toks.insert(pos + k, gt); }
    }
    format!("Usage: {} {}", bin_name, new_toks.join(" "))
}

fn parse_cli() -> clap::ArgMatches {
    let argv: Vec<String> = env::args().collect();
    match cli().try_get_matches_from(&argv) {
        Ok(m) => m,
        Err(e) => {
            let rendered = e.to_string();
            let out = if e.kind() == clap::error::ErrorKind::UnknownArgument {
                fix_unknown_usage(&rendered, &argv[1..])
            } else { rendered };
            if e.use_stderr() {
                eprint!("{}", out);
            } else {
                print!("{}", out);
            }
            std::process::exit(e.exit_code());
        }
    }
}

