#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ThemeKind { Dark, Light }
impl ThemeKind {
    fn selected_bg(&self) -> Color {
        match self { ThemeKind::Dark => Color::Rgb(58, 58, 58), ThemeKind::Light => Color::Rgb(220, 220, 220) }
    }
