fn contains_linefeed_literal(pattern: &str) -> bool {
    // Use regex-syntax AST if available to detect literal '\n' (not class ranges).
    // Fallback: simple scan.
    if let Ok(ast) = regex_syntax::ast::parse::Parser::new().parse(pattern) {
        return ast_has_linefeed(&ast);
    }
    simple_linefeed_scan(pattern)
}

fn ast_has_linefeed(ast: &regex_syntax::ast::Ast) -> bool {
    use regex_syntax::ast::*;
    match ast {
        Ast::Literal(l) => l.c == '\n',
        Ast::Concat(c) => c.asts.iter().any(ast_has_linefeed),
        Ast::Alternation(a) => a.asts.iter().any(ast_has_linefeed),
        Ast::Repetition(r) => ast_has_linefeed(&r.ast),
        Ast::Capture(c) => ast_has_linefeed(&c.ast),
        Ast::Group(g) => ast_has_linefeed(&g.ast),
        Ast::ClassBracketed(cb) => class_set_has_linefeed(&cb.kind),
        _ => false,
    }
}
fn class_set_has_linefeed(set: &regex_syntax::ast::ClassSet) -> bool {
    use regex_syntax::ast::*;
    match set {
        ClassSet::Item(item) => class_item_has_linefeed(item),
        ClassSet::Binary(b) => class_set_has_linefeed(&b.kind),
    }
}
fn class_item_has_linefeed(item: &regex_syntax::ast::ClassSetItem) -> bool {
    use regex_syntax::ast::*;
    match item {
        ClassSetItem::Literal(l) => l.c == '\n',
        ClassSetItem::Bracketed(b) => class_set_has_linefeed(&b.kind),
        ClassSetItem::Union(u) => u.items.iter().any(class_item_has_linefeed),
        _ => false,
    }
}

fn simple_linefeed_scan(pattern: &str) -> bool {
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '\n' => return true,
            '\\' => {
                if i + 1 >= chars.len() { break; }
                let n = chars[i + 1];
                if n == 'n' { return true; }
                if n == '\n' { return true; }
                i += 2;
                continue;
            }
            _ => {}
        }
        i += 1;
    }
    false
}

fn ast_has_uppercase(pattern: &str) -> bool {
    if let Ok(ast) = regex_syntax::ast::parse::Parser::new().parse(pattern) {
        return ast_upper(&ast);
    }
    pattern.chars().any(|c| c.is_uppercase())
}
fn ast_upper(ast: &regex_syntax::ast::Ast) -> bool {
    use regex_syntax::ast::*;
    match ast {
        Ast::Literal(l) => l.c.is_uppercase(),
        Ast::Concat(c) => c.asts.iter().any(ast_upper),
        Ast::Alternation(a) => a.asts.iter().any(ast_upper),
        Ast::Repetition(r) => ast_upper(&r.ast),
        Ast::Capture(c) => ast_upper(&c.ast),
        Ast::Group(g) => ast_upper(&g.ast),
        Ast::ClassBracketed(cb) => class_upper(&cb.kind),
        _ => false,
    }
}
fn class_upper(set: &regex_syntax::ast::ClassSet) -> bool {
    use regex_syntax::ast::*;
    match set {
        ClassSet::Item(item) => class_item_upper(item),
        ClassSet::Binary(b) => class_upper(&b.kind),
    }
}
fn class_item_upper(item: &regex_syntax::ast::ClassSetItem) -> bool {
    use regex_syntax::ast::*;
    match item {
        ClassSetItem::Literal(l) => l.c.is_uppercase(),
        ClassSetItem::Range(r) => r.start.c.is_uppercase() || r.end.c.is_uppercase() || (r.start.c <= 'A' && r.end.c >= 'A') || (r.start.c <= 'Z' && r.end.c >= 'Z' && r.start.c < r.end.c),
        ClassSetItem::Bracketed(b) => class_upper(&b.kind),
        ClassSetItem::Union(u) => u.items.iter().any(class_item_upper),
        _ => false,
    }
