impl Matcher {
    fn build(config: &SearchConfig) -> Result<Matcher, MatcherError> {
        let pattern = &config.pattern;
        // Validate regex syntax as grep does ((?:pattern))
        if !config.fixed_strings {
            let wrapped = format!("(?:{})", pattern);
            if let Err(e) = regex::Regex::new(&wrapped) {
                return Err(MatcherError { kind: MatcherKind::Regex(e) });
            }
            if !config.multiline && contains_linefeed_literal(pattern) {
                return Err(MatcherError { kind: MatcherKind::NotAllowed("\\n".to_string()) });
            }
        } else {
            if !config.multiline && pattern.contains('\n') {
                return Err(MatcherError { kind: MatcherKind::NotAllowed("\\n".to_string()) });
            }
        }
        let case_insensitive = config.ignore_case || (config.smart_case && !ast_has_uppercase(pattern));
        let base = if config.fixed_strings { regex::escape(pattern) } else { pattern.clone() };
        let effective = if config.word_regexp {
            format!(r"(?:^|\W)({})", base)
        } else { base };
        let regex = BytesRegexBuilder::new(&effective)
            .case_insensitive(case_insensitive)
            .multi_line(config.multiline)
            .unicode(true)
            .build()
            .map_err(|_e| {
                // Build failed for effective pattern; report validation-style error if possible
                let wrapped = format!("(?:{})", pattern);
                if let Err(re) = regex::Regex::new(&wrapped) {
                    MatcherError { kind: MatcherKind::Regex(re) }
                } else {
                    // Fall back: use error from a plain build of wrapped pattern with bytes
                    match BytesRegexBuilder::new(&wrapped).build() {
                        Err(be) => {
                            // Convert bytes error to string regex error by rebuilding as string regex
                            let _ = be;
                            MatcherError { kind: MatcherKind::Regex(regex::Regex::new("[").unwrap_err()) }
                        }
                        Ok(_) => MatcherError { kind: MatcherKind::Regex(regex::Regex::new("[").unwrap_err()) },
                    }
                }
            })?;
        Ok(Matcher { regex, word: config.word_regexp, multiline: config.multiline })
    }

    // Find spans (pattern spans) in a haystack
    fn find_spans(&self, haystack: &[u8]) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        if !self.word {
            for m in self.regex.find_iter(haystack) {
                out.push((m.start(), m.end()));
            }
        } else {
            let mut pos = 0usize;
            while pos <= haystack.len() {
                let Some(caps) = self.regex.captures_at(haystack, pos) else { break };
                let Some(g) = caps.get(1) else { break };
                let span = (g.start(), g.end());
                if out.last() != Some(&span) {
                    out.push(span);
                }
                let next = if g.end() > pos { g.end() } else { pos + 1 };
                if next == pos { break; }
                pos = next;
                if g.end() == haystack.len() && g.start() == g.end() { break; }
            }
        }
        out
    }
}

pub fn spawn_search(config: SearchConfig, sender: Sender<SearchMessage>) {
    thread::spawn(move || {
        let matcher = build_matcher_or_panic(&config);
        run_search(&config, &matcher, &sender);
        let _ = sender.send(SearchMessage::Finished);
    });
}

fn build_matcher_or_panic(config: &SearchConfig) -> Matcher {
    let result = Matcher::build(config);
    result
        .expect("Cannot build RegexMatcher")
}

fn run_search(config: &SearchConfig, matcher: &Matcher, sender: &Sender<SearchMessage>) {
    let mut builder = WalkBuilder::new(&config.paths[0]);
    for p in &config.paths[1..] { builder.add(p); }
    builder
        .hidden(!config.hidden)
        .follow_links(config.follow)
        .overrides(config.overrides.clone())
        .types(config.types.clone());

    if let Some((kind, reverse)) = config.sort_state {
        builder.sort_by_file_path(move |a, b| {
            let ord = compare_paths(a, b, kind);
            if reverse { ord.reverse() } else { ord }
        });
        for entry in builder.build() {
            let Ok(entry) = entry else { continue };
            let is_root = entry.depth() == 0;
            let path = entry.path();
            let is_file = if is_root { path.is_file() } else { entry.file_type().map(|t| t.is_file()).unwrap_or(false) };
            if !is_file { continue; }
            if let Some(fr) = search_file(path, matcher) {
                if sender.send(SearchMessage::Result(fr)).is_err() { return; }
            }
        }
    } else {
        let parallel = builder.build_parallel();
        let sender_arc = std::sync::Arc::new(sender.clone());
        // WalkParallel::run expects a factory; use a simple approach with cloned matcher via Arc
        let matcher_arc = std::sync::Arc::new(matcher.clone_regex());
        parallel.run(|| {
            let sender = sender_arc.clone();
            let matcher = matcher_arc.clone();
            Box::new(move |entry| {
                let Ok(entry) = entry else { return ignore::WalkState::Continue };
                let is_root = entry.depth() == 0;
                let path = entry.path();
                let is_file = if is_root { path.is_file() } else { entry.file_type().map(|t| t.is_file()).unwrap_or(false) };
                if !is_file { return ignore::WalkState::Continue; }
                if let Some(fr) = search_file(path, &matcher) {
                    if sender.send(SearchMessage::Result(fr)).is_err() { return ignore::WalkState::Quit; }
                }
                ignore::WalkState::Continue
            })
        });
    }
}

impl Matcher {
    fn clone_regex(&self) -> Matcher {
        Matcher { regex: self.regex.clone(), word: self.word, multiline: self.multiline }
    }
}

fn compare_paths(a: &Path, b: &Path, kind: SortKind) -> Ordering {
    match kind {
        SortKind::Path => a.cmp(b),
        SortKind::Modified => time_of(a, |m| m.modified()).cmp(&time_of(b, |m| m.modified())),
        SortKind::Created => time_of(a, |m| m.created()).cmp(&time_of(b, |m| m.created())),
        SortKind::Accessed => time_of(a, |m| m.accessed()).cmp(&time_of(b, |m| m.accessed())),
    }
}
fn time_of<F: Fn(&fs::Metadata) -> std::io::Result<SystemTime>>(p: &Path, f: F) -> SystemTime {
    let Ok(md) = fs::metadata(p) else { return SystemTime::UNIX_EPOCH };
    f(&md).unwrap_or(SystemTime::UNIX_EPOCH)
}

fn search_file(path: &Path, matcher: &Matcher) -> Option<FileResult> {
    let content = fs::read(path).ok()?;
    // binary detection: NUL in first 64KiB
    let check_len = content.len().min(65536);
    if content[..check_len].contains(&0u8) { return None; }
    let search_content: &[u8] = match content.iter().position(|&b| b == 0) {
        Some(pos) => &content[..pos],
        None => &content[..],
    };
    let mut result_matches: Vec<FileMatch> = Vec::new();
    if matcher.multiline {
        // Build line ranges over full content (use search_content for spans but lines from full content? use search_content)
        let spans = matcher.find_spans(search_content);
        if spans.is_empty() { return None; }
        // line ranges
        let mut ranges: Vec<(usize, usize, usize)> = Vec::new(); // start, end_excl_newline, line_number
        let mut start = 0usize;
        let mut line_no = 1usize;
        for (i, &b) in search_content.iter().enumerate() {
            if b == b'\n' {
                ranges.push((start, i, line_no));
                start = i + 1;
                line_no += 1;
            }
        }
        if start < search_content.len() || search_content.is_empty() {
            if start < search_content.len() {
                ranges.push((start, search_content.len(), line_no));
            }
        }
        // map spans to lines
        let mut per_line: Vec<(usize, Vec<(usize, usize)>)> = Vec::new(); // index into ranges, spans relative to line start
        for (s, e) in spans {
            // find first and last line
            let (first, last) = span_lines(&ranges, s, e, search_content.len());
            let Some(first) = first else { continue };
            let last = last.unwrap_or(first);
            for li in first..=last {
                let (ls, le, _) = ranges[li];
                let cs = if s > ls { s } else { ls };
                let ce = if e < le { e } else { le };
                let rel = if ce > cs { Some((cs - ls, ce - ls)) } else { Some((cs - ls, cs - ls)) };
                if let Some(entry) = per_line.iter_mut().find(|(idx, _)| *idx == li) {
                    if let Some(r) = rel { if !entry.1.contains(&r) { entry.1.push(r); } }
                } else {
                    per_line.push((li, rel.into_iter().collect()));
                }
            }
        }
        per_line.sort_by_key(|(idx, _)| *idx);
        for (li, spans_rel) in per_line {
            let (ls, le, line_no) = ranges[li];
            let line_bytes = &search_content[ls..le];
            let text = match String::from_utf8(line_bytes.to_vec()) {
                Ok(t) => t,
                Err(_) => break,
            };
            let trimmed_len = text.trim_end().len();
            let mut spans_clipped: Vec<(usize, usize)> = spans_rel.iter().map(|&(s, e)| (s.min(trimmed_len), e.min(trimmed_len))).collect();
            spans_clipped.sort();
            spans_clipped.dedup();
            result_matches.push(FileMatch {
                line_number: line_no,
                line_text: text.trim_end().to_string(),
                spans: spans_clipped,
            });
        }
    } else {
        let mut start = 0usize;
        let mut line_no = 1usize;
        let bytes = search_content;
        loop {
            let end = bytes[start..].iter().position(|&b| b == b'\n').map(|o| start + o).unwrap_or(bytes.len());
            let line_bytes = &bytes[start..end];
            let spans = matcher.find_spans(line_bytes);
            if !spans.is_empty() {
                let text = match String::from_utf8(line_bytes.to_vec()) {
                    Ok(t) => t,
                    Err(_) => break,
                };
                let trimmed = text.trim_end();
                let trimmed_len = trimmed.len();
                let mut spans_clipped: Vec<(usize, usize)> = spans.iter().map(|&(s, e)| (s.min(trimmed_len), e.min(trimmed_len))).collect();
                spans_clipped.sort();
                spans_clipped.dedup();
                result_matches.push(FileMatch {
                    line_number: line_no,
                    line_text: trimmed.to_string(),
                    spans: spans_clipped,
                });
            }
            if end >= bytes.len() { break; }
            start = end + 1;
            line_no += 1;
            if start > bytes.len() { break; }
            if start == bytes.len() {
                // trailing newline: no extra line
                break;
            }
        }
    }
    if result_matches.is_empty() { None } else {
        Some(FileResult { path: path.to_string_lossy().to_string(), matches: result_matches })
    }
}

fn span_lines(ranges: &[(usize, usize, usize)], s: usize, e: usize, _len: usize) -> (Option<usize>, Option<usize>) {
    if ranges.is_empty() { return (None, None); }
    let find = |pos: usize, is_end: bool| -> Option<usize> {
        // returns index of line containing pos (pos at newline belongs to that line)
        for (i, &(ls, le, _)) in ranges.iter().enumerate() {
            let next_start = if i + 1 < ranges.len() { ranges[i + 1].0 } else { usize::MAX };
            if pos >= ls && pos < next_start {
                return Some(i);
            }
            if is_end && pos == le && pos >= ls { return Some(i); }
            let _ = le;
        }
        if pos >= ranges.last().unwrap().0 { return Some(ranges.len() - 1); }
        None
    };
    if e > s {
        (find(s, false), find(e - 1, true))
    } else {
        let f = find(s, true);
        (f, f)
    }
}
