fn load_context_lines(path: &str, theme: ThemeKind) -> Vec<ContextLine> {
    let file = File::open(Path::new(path)).expect("Failed to create line highlighter");
    let reader = BufReader::new(file);
    let mut raw_lines: Vec<String> = Vec::new();
    for line in reader.lines() {
        let line = line.expect("Not valid UTF-8");
        raw_lines.push(line);
    }
    let syntax = crate::ui::highlight::SyntaxKind::detect(path, raw_lines.first().map(|s| s.as_str()));
    let mut hl = crate::ui::highlight::Highlighter::new(syntax, theme);
    raw_lines.iter().map(|l| ContextLine { spans: hl.highlight_line(l) }).collect()
}
