use crate::ThemeKind;
use ratatui::style::{Color, Style};
use ratatui::text::Span;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ContextViewerKind { None, Vertical, Horizontal }

#[derive(Clone)]
pub struct ContextLine {
    pub spans: Vec<Span<'static>>,
}

pub struct ContextCache {
    pub path: Option<String>,
    pub lines: Vec<ContextLine>,
}
impl ContextCache {
    pub fn new() -> Self { Self { path: None, lines: Vec::new() } }
    pub fn ensure(&mut self, path: &str, theme: ThemeKind) {
        if self.path.as_deref() == Some(path) { return; }
        let lines = load_context_lines(path, theme);
        self.path = Some(path.to_string());
        self.lines = lines;
    }
}

fn load_context_lines(path: &str, theme: ThemeKind) -> Vec<ContextLine> {
    let file = File::open(Path::new(path)).expect("Failed to create line highlighter");
    let reader = BufReader::new(file);
    let mut raw_lines: Vec<String> = Vec::new();
    for line in reader.lines() {
        let line = line.expect("Not valid UTF-8");
        raw_lines.push(line);
    }
    let syntax = crate::ui::highlight::SyntaxKind::detect(path, raw_lines.first().map(|s| s.as_str()));
    let mut hl = crate::ui::highlight::Highlighter::new(syntax, theme);
    raw_lines.iter().map(|l| ContextLine { spans: hl.highlight_line(l) }).collect()
}
