use crate::ThemeKind;
use ratatui::style::{Color, Style};
use ratatui::text::Span;

// Approximate syntect + base16-ocean highlighting.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Lang { Plain, Rust, Python, Shell, Json, Html, Markdown, C, JavaScript, Go, Makefile, Yaml, Toml, Xml, Css, Java }

#[derive(Clone, Copy)]
pub struct SyntaxKind { pub lang: Lang }

fn fg(theme: ThemeKind) -> Color {
    match theme { ThemeKind::Dark => Color::Rgb(192, 197, 206), ThemeKind::Light => Color::Rgb(79, 91, 102) }
}
pub const COMMENT: Color = Color::Rgb(101, 115, 126);
pub const KEYWORD: Color = Color::Rgb(180, 142, 173);
pub const STRING: Color = Color::Rgb(163, 190, 140);
pub const NUMBER: Color = Color::Rgb(208, 135, 112);
pub const FUNCTION: Color = Color::Rgb(143, 161, 179);
pub const VARIABLE: Color = Color::Rgb(191, 97, 106);
pub const TYPECOL: Color = Color::Rgb(235, 203, 139);
pub const CYAN: Color = Color::Rgb(150, 181, 180);

impl SyntaxKind {
    pub fn detect(path: &str, first_line: Option<&str>) -> Self {
        let name = std::path::Path::new(path).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        let lower_name = name.to_lowercase();
        if lower_name == "makefile" || lower_name.starts_with("makefile.") || lower_name == "gnumakefile" {
            return Self { lang: Lang::Makefile };
        }
        if lower_name == "dockerfile" || lower_name.starts_with("dockerfile.") {
            return Self { lang: Lang::Shell };
        }
        let ext = std::path::Path::new(path).extension().map(|s| s.to_string_lossy().to_lowercase()).unwrap_or_default();
        let lang = match ext.as_str() {
            "rs" => Lang::Rust,
            "py" | "pyi" => Lang::Python,
            "sh" | "bash" | "zsh" | "ksh" | "fish" => Lang::Shell,
            "json" | "jsonl" => Lang::Json,
            "html" | "htm" | "xml" | "xhtml" | "svg" => if ext == "xml" || ext == "svg" { Lang::Xml } else { Lang::Html },
            "md" | "markdown" | "mdown" | "mdx" => Lang::Markdown,
            "c" | "h" | "cpp" | "cc" | "cxx" | "hpp" | "hh" | "cs" | "php" => Lang::C,
            "js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs" | "vue" => Lang::JavaScript,
            "go" => Lang::Go,
            "java" | "kt" | "kts" | "scala" => Lang::Java,
            "yaml" | "yml" => Lang::Yaml,
            "toml" => Lang::Toml,
            "css" | "scss" | "less" => Lang::Css,
            _ => {
                if let Some(fl) = first_line {
                    if fl.starts_with("#!") {
                        if fl.contains("python") { Lang::Python }
                        else if fl.contains("bash") || fl.contains("/sh") || fl.contains("zsh") { Lang::Shell }
                        else if fl.contains("node") { Lang::JavaScript }
                        else if fl.contains("ruby") || fl.contains("perl") { Lang::Python }
                        else { Lang::Plain }
                    } else { Lang::Plain }
                } else { Lang::Plain }
            }
        };
        Self { lang }
    }
}

pub struct Highlighter {
    lang: Lang,
    theme: ThemeKind,
    in_block_comment: bool,
    in_triple: Option<String>,
}
impl Highlighter {
    pub fn new(syntax: SyntaxKind, theme: ThemeKind) -> Self {
        Self { lang: syntax.lang, theme, in_block_comment: false, in_triple: None }
    }
    fn base(&self) -> Color { fg(self.theme) }
    fn span(&self, text: &str, color: Color, out: &mut Vec<Span<'static>>) {
        if text.is_empty() { return; }
        // merge with previous if same color
        out.push(Span::styled(text.to_string(), Style::default().fg(color)));
    }

    pub fn highlight_line(&mut self, line: &str) -> Vec<Span<'static>> {
        match self.lang {
            Lang::Plain => vec![Span::styled(line.to_string(), Style::default().fg(self.base()))],
            Lang::Markdown => self.highlight_markdown(line),
            Lang::Json => self.highlight_simple(line, true),
            _ => self.highlight_code(line),
        }
    }

    fn highlight_markdown(&mut self, line: &str) -> Vec<Span<'static>> {
        let base = self.base();
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') {
            let hash_len = trimmed.chars().take_while(|&c| c == '#').count();
            let prefix_len = line.len() - trimmed.len();
            let mut out = Vec::new();
            if prefix_len > 0 { self.span(&line[..prefix_len], base, &mut out); }
            // syntect: hashes and heading text are blue (FUNCTION)
            self.span(&trimmed[..hash_len], FUNCTION, &mut out);
            let rest = &trimmed[hash_len..];
            if let Some(stripped) = rest.strip_prefix(' ') {
                self.span(" ", base, &mut out);
                self.span(stripped, FUNCTION, &mut out);
            } else {
                self.span(rest, FUNCTION, &mut out);
            }
            return out;
        }
        vec![Span::styled(line.to_string(), Style::default().fg(base))]
    }

    fn highlight_simple(&mut self, line: &str, _json: bool) -> Vec<Span<'static>> {
        // JSON: strings green content, numbers/constants orange, punctuation base
        let base = self.base();
        let mut out = Vec::new();
        let chars: Vec<(usize, char)> = line.char_indices().collect();
        let mut i = 0usize;
        let bytes = line.as_bytes();
        while i < line.len() {
            let c = line[i..].chars().next().unwrap();
            if c == '"' {
                // opening quote base, content string, closing quote base
                self.span("\"", base, &mut out);
                let start = i + 1;
                let mut j = start;
                while j < line.len() {
                    if bytes[j] == b'\\' { j += 2; continue; }
                    if bytes[j] == b'"' { break; }
                    j += 1;
                }
                let end = j.min(line.len());
                self.span(&line[start..end], STRING, &mut out);
                if end < line.len() { self.span("\"", base, &mut out); i = end + 1; } else { i = end; }
                continue;
            }
            if c.is_ascii_digit() || (c == '-' && i + 1 < line.len() && line[i+1..].chars().next().map(|x| x.is_ascii_digit()).unwrap_or(false)) {
                let mut j = i;
                while j < line.len() && (line[j..].chars().next().map(|x| x.is_ascii_digit() || x == '.' || x == 'e' || x == 'E' || x == '+' || x == '-').unwrap_or(false)) { j += 1; }
                self.span(&line[i..j], NUMBER, &mut out);
                i = j; continue;
            }
            // keywords true/false/null
            let mut matched = false;
            for kw in ["true", "false", "null"] {
                if line[i..].starts_with(kw) {
                    let after = i + kw.len();
                    if after >= line.len() || !line[after..].chars().next().map(|x| x.is_alphanumeric() || x == '_').unwrap_or(false) {
                        self.span(kw, NUMBER, &mut out);
                        i = after; matched = true; break;
                    }
                }
            }
            if matched { continue; }
            let mut j = i + c.len_utf8();
            // consume consecutive base chars until special
            while j < line.len() {
                let nc = line[j..].chars().next().unwrap();
                if nc == '"' || nc.is_ascii_digit() { break; }
                j += nc.len_utf8();
            }
            self.span(&line[i..j], base, &mut out);
            i = j;
            let _ = &chars;
        }
        if out.is_empty() { out.push(Span::styled(String::new(), Style::default().fg(base))); }
        out
    }

    fn keywords(&self) -> &'static [&'static str] {
        match self.lang {
            Lang::Rust => &["fn", "let", "mut", "pub", "struct", "enum", "impl", "trait", "use", "mod", "match", "if", "else", "for", "while", "loop", "return", "const", "static", "ref", "move", "type", "where", "in", "break", "continue", "crate", "self", "Self", "super", "async", "await", "dyn", "unsafe", "extern", "true", "false"],
            Lang::Python => &["import", "from", "def", "return", "class", "if", "elif", "else", "for", "while", "try", "except", "finally", "with", "as", "pass", "lambda", "None", "True", "False", "in", "is", "not", "and", "or", "yield", "async", "await", "global", "nonlocal", "raise", "break", "continue", "print"],
            Lang::Shell | Lang::Makefile => &["if", "then", "else", "elif", "fi", "for", "while", "do", "done", "case", "esac", "function", "return", "in", "echo", "export", "local", "readonly", "shift", "exit", "source", "set"],
            Lang::C => &["int", "char", "void", "float", "double", "long", "short", "unsigned", "signed", "const", "static", "struct", "enum", "union", "typedef", "if", "else", "for", "while", "do", "return", "break", "continue", "switch", "case", "default", "sizeof", "extern", "volatile", "class", "public", "private", "protected", "virtual", "template", "typename", "namespace", "using", "new", "delete", "this", "nullptr", "true", "false"],
            Lang::JavaScript => &["const", "let", "var", "function", "return", "if", "else", "for", "while", "class", "extends", "new", "import", "export", "from", "default", "async", "await", "try", "catch", "finally", "throw", "switch", "case", "break", "continue", "typeof", "instanceof", "in", "of", "this", "true", "false", "null", "undefined", "void", "delete", "yield"],
            Lang::Go => &["package", "import", "func", "var", "const", "type", "struct", "interface", "map", "chan", "go", "defer", "return", "if", "else", "for", "range", "switch", "case", "break", "continue", "select", "true", "false", "nil"],
            Lang::Java => &["package", "import", "class", "interface", "enum", "public", "private", "protected", "static", "final", "void", "int", "long", "double", "float", "boolean", "char", "byte", "short", "return", "if", "else", "for", "while", "new", "this", "super", "extends", "implements", "try", "catch", "finally", "throw", "throws", "true", "false", "null", "abstract", "volatile", "synchronized"],
            _ => &["if", "else", "for", "while", "return", "function", "class", "import", "from", "true", "false", "null"],
        }
    }

    fn highlight_code(&mut self, line: &str) -> Vec<Span<'static>> {
        if self.lang == Lang::Html || self.lang == Lang::Xml {
            return self.highlight_html(line);
        }
        let base = self.base();
        let mut out: Vec<Span<'static>> = Vec::new();
        // triple string continuation
        if let Some(delim) = self.in_triple.clone() {
            if let Some(pos) = line.find(&delim) {
                let (content, rest) = line.split_at(pos + delim.len());
                // content includes closing delim: syntect puts delim as base? approximate: content before closing as string
                let inner = &content[..content.len().saturating_sub(delim.len())];
                self.span(inner, STRING, &mut out);
                self.span(&delim, base, &mut out);
                self.in_triple = None;
                let remaining = self.highlight_code_fragment(rest);
                out.extend(remaining);
                return out;
            } else {
                self.span(line, STRING, &mut out);
                return out;
            }
        }
        self.highlight_code_inner(line, &mut out);
        if out.is_empty() { out.push(Span::styled(String::new(), Style::default().fg(base))); }
        out
    }

    fn highlight_code_fragment(&mut self, line: &str) -> Vec<Span<'static>> {
        let mut out = Vec::new();
        self.highlight_code_inner(line, &mut out);
        out
    }

    fn highlight_code_inner(&mut self, line: &str, out: &mut Vec<Span<'static>>) {
        let base = self.base();
        // Whole-line comment detection for shell/python (including shebang)
        let trimmed = line.trim_start();
        let line_comment: Option<&str> = match self.lang {
            Lang::Python | Lang::Shell | Lang::Makefile | Lang::Yaml | Lang::Toml => Some("#"),
            Lang::Rust | Lang::C | Lang::JavaScript | Lang::Go | Lang::Java | Lang::Css => Some("//"),
            _ => None,
        };
        if self.lang == Lang::Makefile && !line.starts_with('\t') && line.contains(':') && !trimmed.starts_with('#') {
            // target rule handled below generically
        }
        if let Some(lc) = line_comment {
            if trimmed.starts_with(lc) && (self.lang != Lang::Rust || trimmed.starts_with("//")) {
                let prefix_len = line.len() - trimmed.len();
                if prefix_len > 0 { self.span(&line[..prefix_len], base, out); }
                self.span(trimmed, COMMENT, out);
                return;
            }
        }
        if self.in_block_comment {
            if let Some(pos) = line.find("*/") {
                let (c, rest) = line.split_at(pos + 2);
                self.span(c, COMMENT, out);
                self.in_block_comment = false;
                self.highlight_code_inner(rest, out);
                return;
            } else {
                self.span(line, COMMENT, out);
                return;
            }
        }
        // Tokenize
        let mut i = 0usize;
        let chars: Vec<char> = line.chars().collect();
        let _ = chars;
        while i < line.len() {
            let rest = &line[i..];
            let c = rest.chars().next().unwrap();
            // block comment start
            if rest.starts_with("/*") {
                if let Some(pos) = rest[2..].find("*/") {
                    let comment = &rest[..pos + 4];
                    self.span(comment, COMMENT, out);
                    i += comment.len();
                    continue;
                } else {
                    self.span(rest, COMMENT, out);
                    self.in_block_comment = true;
                    return;
                }
            }
            // line comment start (only when not in string; we process sequentially so ok)
            if let Some(lc) = line_comment {
                if rest.starts_with(lc) {
                    // For C-like, "//" ; for python "#"
                    self.span(rest, COMMENT, out);
                    return;
                }
            }
            if self.lang == Lang::Shell && rest.starts_with("#") && (i == 0 || line[..i].ends_with(char::is_whitespace)) {
                self.span(rest, COMMENT, out);
                return;
            }
            // strings
            if c == '"' || c == '\'' || c == '`' {
                // Check triple for python
                if self.lang == Lang::Python && (rest.starts_with("\"\"\"") || rest.starts_with("'''")) {
                    let delim = &rest[..3];
                    if let Some(pos) = rest[3..].find(delim) {
                        self.span(delim, base, out);
                        let inner = &rest[3..3 + pos];
                        self.span(inner, STRING, out);
                        self.span(delim, base, out);
                        i += 3 + pos + 3;
                        continue;
                    } else {
                        self.span(delim, base, out);
                        self.span(&rest[3..], STRING, out);
                        self.in_triple = Some(delim.to_string());
                        return;
                    }
                }
                let quote = c;
                self.span(&quote.to_string(), base, out);
                let mut j = i + quote.len_utf8();
                let mut closed = false;
                while j < line.len() {
                    let cj = line[j..].chars().next().unwrap();
                    if cj == '\\' { j += 1 + (if j + 1 < line.len() { line[j+1..].chars().next().map(|x| x.len_utf8()).unwrap_or(0) } else { 0 }); continue; }
                    if cj == quote { closed = true; break; }
                    // shell interpolation: handle $VAR inside double quotes
                    if quote == '"' && cj == '$' && self.lang == Lang::Shell {
                        break;
                    }
                    j += cj.len_utf8();
                }
                if j > i + 1 {
                    let content = &line[i + 1..j.min(line.len())];
                    // For shell $-split, content before $ is string, handle next separately
                    self.span(content, STRING, out);
                }
                if j < line.len() && line[j..].starts_with('$') && quote == '"' && self.lang == Lang::Shell {
                    // $ sign base, variable name red
                    self.span("$", base, out);
                    let mut k = j + 1;
                    if k < line.len() && line[k..].starts_with('{') {
                        let mut e = k + 1;
                        while e < line.len() && line[e..].chars().next().map(|x| x.is_alphanumeric() || x == '_' || x == '}').unwrap_or(false) { e += line[e..].chars().next().unwrap().len_utf8(); }
                        self.span(&line[k..e], VARIABLE, out);
                        i = e;
                        // continue inside string: need to resume string scanning crudely - treat rest as fragment starting mid string
                        // Find closing quote
                        // Simplify: highlight remainder as string if it leads to closing quote
                        // We'll continue main loop which will see closing quote as start of new string; acceptable approximation
                        continue;
                    } else {
                        while k < line.len() && line[k..].chars().next().map(|x| x.is_alphanumeric() || x == '_').unwrap_or(false) { k += line[k..].chars().next().unwrap().len_utf8(); }
                        if k > j + 1 { self.span(&line[j+1..k], VARIABLE, out); }
                        i = k;
                        continue;
                    }
                }
                if closed {
                    self.span(&quote.to_string(), base, out);
                    i = j + quote.len_utf8();
                } else {
                    i = line.len();
                }
                continue;
            }
            // numbers
            if c.is_ascii_digit() {
                let mut j = i;
                // hex etc
                while j < line.len() {
                    let cj = line[j..].chars().next().unwrap();
                    if cj.is_alphanumeric() || cj == '.' || cj == '_' { j += cj.len_utf8(); } else { break; }
                }
                self.span(&line[i..j], NUMBER, out);
                i = j; continue;
            }
            // identifiers / keywords
            if c.is_alphabetic() || c == '_' {
                let mut j = i;
                while j < line.len() {
                    let cj = line[j..].chars().next().unwrap();
                    if cj.is_alphanumeric() || cj == '_' { j += cj.len_utf8(); } else { break; }
                }
                let word = &line[i..j];
                let prev_nonspace = line[..i].trim_end().chars().last();
                // definition names
                let is_def_name = match self.lang {
                    Lang::Rust => prev_nonspace_is_keyword(&line[..i], &["fn", "struct", "enum", "trait", "type", "mod", "impl"]),
                    Lang::Python => prev_nonspace_is_keyword(&line[..i], &["def", "class"]),
                    _ => false,
                };
                if self.keywords().contains(&word) {
                    // Python's print keyword above: syntect treats print as builtin function maybe base; handled as keyword yields purple - differs but acceptable
                    if self.lang == Lang::Python && word == "print" {
                        self.span(word, base, out);
                    } else {
                        self.span(word, KEYWORD, out);
                    }
                } else if is_def_name {
                    self.span(word, FUNCTION, out);
                } else if self.lang == Lang::Python && is_python_param(&line, i, j) {
                    self.span(word, VARIABLE, out);
                } else if (word.chars().next().map(|x| x.is_uppercase()).unwrap_or(false)) && matches!(self.lang, Lang::Rust | Lang::C | Lang::Java | Lang::Go) {
                    // type-ish
                    self.span(word, FUNCTION, out);
                } else if self.lang == Lang::Shell || self.lang == Lang::Makefile {
                    // first word as command: cyan if at start (after whitespace)
                    if line[..i].trim().is_empty() {
                        self.span(word, CYAN, out);
                    } else {
                        self.span(word, base, out);
                    }
                } else if self.lang == Lang::Makefile && line[..i].trim().is_empty() {
                    self.span(word, CYAN, out);
                } else {
                    self.span(word, base, out);
                }
                i = j; continue;
            }
            // variable $ in shell / etc
            if c == '$' && (self.lang == Lang::Shell || self.lang == Lang::Makefile) {
                self.span("$", base, out);
                let mut j = i + 1;
                if j < line.len() && line[j..].starts_with('{') {
                    let mut e = j;
                    while e < line.len() && { let cc = line[e..].chars().next().unwrap(); cc.is_alphanumeric() || cc == '_' || cc == '{' || cc == '}' } { e += line[e..].chars().next().unwrap().len_utf8(); }
                    self.span(&line[j..e], VARIABLE, out);
                    i = e; continue;
                }
                while j < line.len() && line[j..].chars().next().map(|x| x.is_alphanumeric() || x == '_').unwrap_or(false) { j += line[j..].chars().next().unwrap().len_utf8(); }
                if j > i + 1 { self.span(&line[i+1..j], VARIABLE, out); }
                i = j; continue;
            }
            // single char base (consume possibly grouped punctuation/spaces)
            let mut j = i + c.len_utf8();
            while j < line.len() {
                let nc = line[j..].chars().next().unwrap();
                if nc.is_alphanumeric() || nc == '_' || nc == '"' || nc == '\'' || nc == '`' || nc == '$' && (self.lang == Lang::Shell) { break; }
                if line[j..].starts_with("/*") { break; }
                if let Some(lc) = line_comment { if line[j..].starts_with(lc) { break; } }
                j += nc.len_utf8();
                // stop after a few? keep grouping punctuation
                if j - i > 8 { break; }
            }
            self.span(&line[i..j], base, out);
            i = j;
        }
    }

    fn highlight_html(&mut self, line: &str) -> Vec<Span<'static>> {
        let base = self.base();
        let mut out = Vec::new();
        let mut i = 0usize;
        while i < line.len() {
            if line[i..].starts_with("<!--") {
                if let Some(pos) = line[i..].find("-->") {
                    self.span(&line[i..i+pos+3], COMMENT, &mut out);
                    i += pos + 3; continue;
                } else { self.span(&line[i..], COMMENT, &mut out); break; }
            }
            let c = line[i..].chars().next().unwrap();
            if c == '<' {
                self.span("<", base, &mut out);
                i += 1;
                if i < line.len() && line[i..].starts_with('/') { self.span("/", base, &mut out); i += 1; }
                // tag name
                let mut j = i;
                while j < line.len() && { let cc = line[j..].chars().next().unwrap(); cc.is_alphanumeric() || cc == '-' || cc == '_' } { j += line[j..].chars().next().unwrap().len_utf8(); }
                if j > i { self.span(&line[i..j], VARIABLE, &mut out); i = j; }
                // attributes until >
                while i < line.len() && !line[i..].starts_with('>') {
                    let cc = line[i..].chars().next().unwrap();
                    if cc.is_alphabetic() || cc == '-' || cc == '_' {
                        let mut k = i;
                        while k < line.len() && { let c2 = line[k..].chars().next().unwrap(); c2.is_alphanumeric() || c2 == '-' || c2 == '_' || c2 == ':' } { k += line[k..].chars().next().unwrap().len_utf8(); }
                        self.span(&line[i..k], NUMBER, &mut out);
                        i = k; continue;
                    }
                    if cc == '"' || cc == '\'' {
                        let mut inner = self.highlight_simple(&line[i..], false);
                        // highlight_simple will handle quoted string with base quotes/string content
                        // But it processes to end of line; we need segment up to closing quote
                        // Simpler manual:
                        let quote = cc;
                        // undo: use manual
                        let _ = &mut inner;
                        self.span(&quote.to_string(), base, &mut out);
                        let mut k = i + 1;
                        while k < line.len() && line[k..].chars().next().unwrap() != quote { k += line[k..].chars().next().unwrap().len_utf8(); }
                        self.span(&line[i+1..k], STRING, &mut out);
                        if k < line.len() { self.span(&quote.to_string(), base, &mut out); i = k + 1; } else { i = k; }
                        continue;
                    }
                    self.span(&cc.to_string(), base, &mut out);
                    i += cc.len_utf8();
                }
                if i < line.len() && line[i..].starts_with('>') { self.span(">", base, &mut out); i += 1; }
                continue;
            }
            // text
            let mut j = i;
            while j < line.len() && !line[j..].starts_with('<') { j += line[j..].chars().next().unwrap().len_utf8(); }
            self.span(&line[i..j], base, &mut out);
            i = j;
        }
        if out.is_empty() { out.push(Span::styled(String::new(), Style::default().fg(base))); }
        out
    }
}

fn prev_nonspace_is_keyword(prefix: &str, keywords: &[&str]) -> bool {
    let t = prefix.trim_end();
    keywords.iter().any(|kw| {
        if t.ends_with(kw) {
            let before = &t[..t.len() - kw.len()];
            before.is_empty() || before.chars().last().map(|c| !c.is_alphanumeric() && c != '_').unwrap_or(true)
        } else { false }
    })
}
fn is_python_param(line: &str, start: usize, _end: usize) -> bool {
    // crude: inside def foo( ... ) parens on same line before a ')'
    let before = &line[..start];
    if let Some(def_pos) = before.rfind("def ") {
        let after_def = &before[def_pos..];
        if after_def.contains('(') && !after_def.contains(')') {
            return true;
        }
    }
    false
}
