    let mut out: Vec<Span<'static>> = Vec::new();
    let mut cur = String::new();
    let mut cur_matched: Option<bool> = None;
    let mut flush = |cur: &mut String, cur_matched: &mut Option<bool>, out: &mut Vec<Span<'static>>| {
        if let Some(m) = *cur_matched {
