{"command":"python3 - << 'PY'
import pathlib
p=pathlib.Path('src/main.rs'); s=p.read_text()
s=s.replace('''    if matches.get_flag("type_list") {
        print!("{}", include_str!("types.txt"));
        return Ok(());
    }''','''    if matches.get_flag("type_list") {
        use std::io::Write;
        let mut out = io::stdout().lock();
        for line in include_str!("types.txt").lines() {
            writeln!(out, "{}", line)?;
        }
        return Ok(());
    }''')
p.write_text(s)
PY
cargo build --offline -q 2>&1 | tail -2
./target/debug/igrep --type-list | head -1; echo "PIPESTATUS ${PIPESTATUS[@]}"
diff <(./executable --type-list) <(./target/debug/igrep --type-list) && echo TYPES_OK"}

